const setInitialWorkerGroupPrimaryPool = `-- name: SetInitialWorkerGroupPrimaryPool :one
WITH selection AS (
    SELECT worker_groups.id AS worker_group_id,
           worker_pools.id AS worker_pool_id,
           worker_groups.primary_pool_id IS NULL
           AND NOT EXISTS (
               SELECT 1 FROM worker_pools AS other
                WHERE other.worker_group_id = worker_groups.id
                  AND other.id <> worker_pools.id
                  AND other.sealed_at IS NOT NULL
           ) AS set_primary
      FROM worker_groups
      JOIN worker_pools
        ON worker_pools.worker_group_id = worker_groups.id
       AND worker_pools.id = $1
       AND worker_pools.status = 'active'
     WHERE worker_groups.id = $2
)
UPDATE worker_groups
   SET primary_pool_id = CASE
           WHEN selection.set_primary THEN selection.worker_pool_id
           ELSE worker_groups.primary_pool_id
       END,
       claim_version = worker_groups.claim_version + CASE
           WHEN selection.set_primary THEN 1
           ELSE 0
       END,
       updated_at = CASE
           WHEN selection.set_primary THEN now()
           ELSE worker_groups.updated_at
       END
  FROM selection
 WHERE worker_groups.id = selection.worker_group_id
RETURNING worker_groups.id, worker_groups.capacity_observed_at, worker_groups.capacity_supply_fingerprint, worker_groups.capacity_pools, worker_groups.token_id, worker_groups.region_id, worker_groups.name, worker_groups.description, worker_groups.status, worker_groups.claim_version, worker_groups.primary_pool_id, worker_groups.created_at, worker_groups.updated_at
`

type SetInitialWorkerGroupPrimaryPoolParams struct {
	WorkerPoolID  pgtype.UUID `json:"worker_pool_id"`
	WorkerGroupID pgtype.UUID `json:"worker_group_id"`
}

func (q *Queries) SetInitialWorkerGroupPrimaryPool(ctx context.Context, arg SetInitialWorkerGroupPrimaryPoolParams) (WorkerGroup, error) {
	row := q.db.QueryRow(ctx, setInitialWorkerGroupPrimaryPool, arg.WorkerPoolID, arg.WorkerGroupID)
	var i WorkerGroup
	err := row.Scan(
		&i.ID,
		&i.CapacityObservedAt,
		&i.CapacitySupplyFingerprint,
		&i.CapacityPools,
		&i.TokenID,
		&i.RegionID,
		&i.Name,
		&i.Description,
		&i.Status,
		&i.ClaimVersion,
		&i.PrimaryPoolID,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}

